   y[0] = 0.13585 * v[3] + -0.1197 * v[3] + 0.425 * v[8] + 0.39225 * v[13] + 0.093 * v[3] + 0.09465 * v[19] + 6.28213797648769e-11 * v[26] + 0.1173 * v[4] + 0.0005 * v[22];
